// Bundle the same versions as Web, offline. Run after changing either xterm dependency.
const fs = require("node:fs");
const path = require("node:path");
const root = path.resolve(__dirname, "..");
const read = (file) =>
  fs
    .readFileSync(path.join(root, "node_modules", file), "utf8")
    .replace(/\/\/# sourceMappingURL=.*$/gm, "");
const assets = {
  xtermJs: read("@xterm/xterm/lib/xterm.js"),
  fitJs: read("@xterm/addon-fit/lib/addon-fit.js"),
  // Notices are retained in terminal-licenses.txt; omit upstream CSS comments.
  xtermCss: read("@xterm/xterm/css/xterm.css").replace(/\/\*[\s\S]*?\*\//g, ""),
};
const output =
  "// Generated by scripts/generate-terminal-assets.js. Xterm MIT licenses are in terminal-licenses.txt.\n" +
  Object.entries(assets)
    .map(
      ([name, value]) => `export const ${name} = ${JSON.stringify(value)};\n`,
    )
    .join("");
const target = path.join(root, "src/features/ssh/terminalAssets.generated.ts");
const licenseTarget = path.join(root, "src/features/ssh/terminal-licenses.txt");
const licenses =
  ["@xterm/xterm", "@xterm/addon-fit"]
    .map((name) => `${name}\n${read(`${name}/LICENSE`).trimEnd()}`)
    .join("\n\n") + "\n";
if (process.argv.includes("--check")) {
  if (
    fs.readFileSync(target, "utf8") !== output ||
    fs.readFileSync(licenseTarget, "utf8") !== licenses
  )
    throw new Error(
      "Offline terminal assets are stale; run node scripts/generate-terminal-assets.js",
    );
} else {
  fs.writeFileSync(target, output);
  fs.writeFileSync(licenseTarget, licenses);
}
